// apply-halaman5.mjs — (1) FIX bug katalog "Report of Doc.Req" kosong (kolom N_tahun
//   bertipe YEAR bikin .trim() error; fixText kini aman untuk angka/tahun/tanggal).
//   (2) Halaman Telepon Penting (/telepon-penting) — 3 kolom PT DI/Bandung/Nasional.
//   (3) Halaman Sekilas Dittek (/sekilas-dittek) — galeri foto + pagination.
//   Gambar via /gambar/<file> (taruh di static/gambar/), seperti /dokumen/ untuk PDF.
// PRASYARAT: jalankan SETELAH apply-dinamis..apply-halaman4 (script 1 s/d 8).
// Cara pakai (dari root project):
//     node apply-halaman5.mjs
//     npm run dev     (WAJIB restart penuh — ada route baru)
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["src/lib/server/portal/transform.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/lib/server/db/schema.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/utils.ts", ''],
  ["src/lib/data/nav.ts", ''],
  ["src/routes/telepon-penting/+page.server.ts", ''],
  ["src/routes/telepon-penting/+page.svelte", ''],
  ["src/routes/sekilas-dittek/+page.server.ts", ''],
  ["src/routes/sekilas-dittek/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis.');
console.log('Restart dev server (WAJIB): npm run dev');
console.log('- Katalog Our Library "Report of Doc.Req" sekarang tampil datanya.');
console.log('- Telepon Penting: menu Information > Telepon Penting → /telepon-penting.');
console.log('- Sekilas Dittek: menu Pojok Media > Sekilas Dittek → /sekilas-dittek.');
console.log('- Foto Sekilas: taruh di static/gambar/ (URL /gambar/<file>).');
